// Получаем все входящие элементы правильно
const items = $input.all();
const results = [];

// Проходимся по каждому элементу
for (const item of items) {
  // В n8n данные лежат внутри свойства .json
  const task = item.json; 

  const name = task.name || '';
  const notes = task.notes || '';
  const product = name.replace(/^новый товар[:\s]*/i, '').trim() || name.trim();
  const certMatch = notes.match(/(GMP|ISO|HACCP|FDA|CE|SGS|Halal|Kosher)/gi);
  const moqMatch = notes.match(/MOQ[:\s]*(\d+)/i);
  results.push({
    taskId: task.gid,
    product,
    notes,
    requiredCerts: certMatch ? [...new Set(certMatch)].join(', ') : 'не указаны',
    moq: moqMatch ? moqMatch[1] : 'не указано',
    assignee: task.assignee?.name || 'не назначен',
    searchDate: new Date().toLocaleDateString('ru-RU')
  });
}
return results;

const raw = $input.first().json.output || '';
const cleaned = raw.replace(/```json/gi,'').replace(/```/g,'').trim();
let factories;
try { factories = JSON.parse(cleaned); }
catch(e) {
  const m = cleaned.match(/\[.*\]/s);
  if(m) factories = JSON.parse(m[0]);
  else throw new Error('Cannot parse factory list: ' + cleaned.substring(0,200));
}
if(!Array.isArray(factories)) factories = [factories];
const ctx = $('Parse ТЗ').first().json;
return [{ json: { ...ctx, factories, factoryCount: factories.length } }];

const raw = $input.first().json.output || '';
const cleaned = raw.replace(/```json/gi,'').replace(/```/g,'').trim();
let analysis;
try { analysis = JSON.parse(cleaned); }
catch(e) {
  const m = cleaned.match(/\{.*\}/s);
  if(m) analysis = JSON.parse(m[0]);
  else throw new Error('Cannot parse analysis: ' + cleaned.substring(0,200));
}

const ctx = $('Parse Factory List').first().json;
const topPick = analysis.topPick || analysis.rankedFactories?.[0]?.factoryName || 'N/A';
const ranked = analysis.rankedFactories || [];

// === TELEGRAM MESSAGE ===
let tg = `🏭 *Поиск фабрик завершён*\n`;
tg += `📦 Товар: *${ctx.product}*\n`;
tg += `📅 Дата: ${ctx.searchDate}\n`;
tg += `🔍 Найдено фабрик: ${ctx.factoryCount}\n\n`;

tg += `✅ *Рекомендация: ${topPick}*\n`;
tg += `${analysis.topPickReason || ''}\n\n`;

tg += `📊 *Рейтинг фабрик:*\n`;

for(const f of ranked) {
  const reseller = f.isLikelyReseller ? ' ⚠️ перекупщик' : '';
  // Берём телефон из объекта фабрики f
  // Предполагаем, что ключ называется 'Phone number' или 'phone'
  const phone = f['Phone number'] || f.phone || 'не указан';

  tg += `${f.rank}\. *${f.factoryName}* — ${f.scoreTotal}/100${reseller}\n`;
  tg += `    📞 Тел: ${phone}\n`; // Добавили строку с номером
  tg += `    💰 ${f.fobPricePerKg} | ⏱ ${f.leadTimeDays} | ${f.recommendation || ''}\n\n`;
}

if(analysis.eliminatedFactories?.length) {
  tg += `\n❌ *Исключены:*\n`;
  for(const e of analysis.eliminatedFactories) {
    tg += `• ${e.name}: ${e.reason}\n`;
  }
}

if(analysis.warningsAndRisks?.length) {
  tg += `\n⚠️ *Риски:*\n`;
  for(const w of analysis.warningsAndRisks) tg += `• ${w}\n`;
}

if(analysis.nextSteps?.length) {
  tg += `\n📋 *Следующие шаги:*\n`;
  analysis.nextSteps.forEach((s,i) => { tg += `${i+1}\. ${s}\n`; });
}

// === GOOGLE SHEETS ROWS — one row per factory ===
const sheetRows = ranked.map(f => ({
  date: ctx.searchDate,
  product: ctx.product,
  taskId: ctx.taskId,
  rank: f.rank,
  factoryName: f.factoryName,
  location: f.location || '',
  platform: f.platform || '',
  scoreTotal: f.scoreTotal,
  scorePrice: f.scoreBreakdown?.price || '',
  scoreReliability: f.scoreBreakdown?.reliability || '',
  scoreExport: f.scoreBreakdown?.exportReadiness || '',
  scoreTerms: f.scoreBreakdown?.terms || '',
  scoreSpecialization: f.scoreBreakdown?.specialization || '',
  fobPricePerKg: f.fobPricePerKg || '',
  moq: f.moq || '',
  leadTimeDays: f.leadTimeDays || '',
  rating: f.rating || '',
  oemAvailable: f.oemAvailable ? 'Да' : 'Нет',
  accepts30Prepayment: f.accepts30Prepayment ? 'Да' : 'Нет',
  availableCerts: (f.availableCerts || []).join(', '),
  exportCountries: (f.exportCountries || []).join(', '),
  isLikelyReseller: f.isLikelyReseller ? 'Да' : 'Нет',
  recommendation: f.recommendation || '',
  riskFlags: (f.riskFlags || []).join('; '),
  isTopPick: f.rank === 1 ? 'ДА' : ''
}));

return [{
  json: {
    ...ctx,
    analysis,
    topPick,
    telegramMessage: tg,
    sheetRows
  }
}];

// Unpack sheetRows array into individual items for SplitInBatches
const rows = $input.first().json.sheetRows;
const base = $input.first().json;
return rows.map(row => ({ json: { ...base, currentRow: row } }));
